import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.1
.target sm_89
.address_size 64
// Register-blocked 3D convolution with a three-stage input-channel pipeline.
// Each CTA computes an 8x8x16 output tile with 128 threads; every thread
// accumulates a 2x4 (HxW) register block so each shared-memory input row is
// reused for two output rows, cutting shared-memory load traffic per FMA.
// The 10x10x18 input halo is padded to a 20-float row pitch so every row is
// 16-byte aligned, then staged with vectorized cp.async copies in a double buffer.
.extern .shared .align 16 .b8 s_in[];
.visible .entry conv3d_f32_sm89(
    .param .u64 p_in,
    .param .u64 p_w,
    .param .u64 p_out
)
{
    .reg .pred %p0, %p1, %p2, %p3, %p_store;
    .reg .u32 %r_bid, %r_tid, %r_tmp, %r_tmp2;
    .reg .u32 %r_n, %r_rem, %r_oc, %r_rem2, %r_tod, %r_rem3, %r_toh, %r_tow;
    .reg .u32 %r_id0, %r_ih0, %r_iw0;
    .reg .u32 %r_i, %r_ic, %r_stage_ic, %r_stage_buf;
    .reg .u32 %r_kd, %r_kh, %r_kw, %r_id, %r_ih, %r_iw;
    .reg .u32 %r_od, %r_oh, %r_ow, %r_kdl, %r_khl, %r_kwl;
    .reg .u32 %r_sbase, %r_soff, %r_inA, %r_threadA, %r_wA;
    .reg .b64 %rd_in, %rd_w, %rd_out, %rd_off, %rd_addr, %rd_sgen;
    .reg .f32 %f_acc0, %f_acc1, %f_acc2, %f_acc3, %f_acc4, %f_acc5, %f_acc6, %f_acc7;
    .reg .f32 %f_x0, %f_x1, %f_x2, %f_x3, %f_x4, %f_x5;
    .reg .f32 %f_b0, %f_b1, %f_b2, %f_b3, %f_b4, %f_b5;
    ld.param.u64 %rd_in, [p_in];
    ld.param.u64 %rd_w, [p_w];
    ld.param.u64 %rd_out, [p_out];
    mov.u32 %r_bid, %ctaid.x;
    mov.u32 %r_tid, %tid.x;
    mov.u64 %rd_sgen, s_in;
    cvt.u32.u64 %r_sbase, %rd_sgen;
    // decompose block id -> (n, oc, tod, toh, tow)
    div.u32 %r_n, %r_bid, 16384;
    mul.lo.u32 %r_tmp, %r_n, 16384;
    sub.u32 %r_rem, %r_bid, %r_tmp;
    div.u32 %r_oc, %r_rem, 256;
    mul.lo.u32 %r_tmp, %r_oc, 256;
    sub.u32 %r_rem2, %r_rem, %r_tmp;
    div.u32 %r_tod, %r_rem2, 32;
    mul.lo.u32 %r_tmp, %r_tod, 32;
    sub.u32 %r_rem3, %r_rem2, %r_tmp;
    div.u32 %r_toh, %r_rem3, 4;
    mul.lo.u32 %r_tmp, %r_toh, 4;
    sub.u32 %r_tow, %r_rem3, %r_tmp;
    shl.b32 %r_id0, %r_tod, 3;
    shl.b32 %r_ih0, %r_toh, 3;
    shl.b32 %r_iw0, %r_tow, 4;
    // ---- stage 81 weights at smem byte offset 8000 ----
    setp.lt.u32 %p0, %r_tid, 81;
    @!%p0 bra $Lwt_done;
    mul.lo.u32 %r_tmp, %r_oc, 81;
    add.u32 %r_tmp, %r_tmp, %r_tid;
    cvt.u64.u32 %rd_off, %r_tmp;
    mul.lo.u64 %rd_off, %rd_off, 4;
    add.u64 %rd_addr, %rd_w, %rd_off;
    mul.lo.u32 %r_tmp, %r_tid, 4;
    add.u32 %r_soff, %r_sbase, %r_tmp;
    cp.async.ca.shared.global [%r_soff+8000], [%rd_addr], 4;
$Lwt_done:
    // ---- stage input channel 0 into buffer 0 with 16-byte cp.async ----
    mov.u32 %r_stage_ic, 0;
    mov.u32 %r_stage_buf, 0;
    mov.u32 %r_i, %r_tid;
$Lstage0:
    setp.lt.u32 %p0, %r_i, 500;
    @!%p0 bra $Lstage0_done;
    div.u32 %r_kd, %r_i, 50;
    mul.lo.u32 %r_tmp, %r_kd, 50;
    sub.u32 %r_rem, %r_i, %r_tmp;
    div.u32 %r_kh, %r_rem, 5;
    mul.lo.u32 %r_tmp, %r_kh, 5;
    sub.u32 %r_kw, %r_rem, %r_tmp;
    add.u32 %r_id, %r_id0, %r_kd;
    add.u32 %r_ih, %r_ih0, %r_kh;
    shl.b32 %r_tmp, %r_kw, 2;
    add.u32 %r_iw, %r_iw0, %r_tmp;
    setp.lt.u32 %p1, %r_id, 64;
    setp.lt.u32 %p2, %r_ih, 64;
    and.pred %p1, %p1, %p2;
    sub.u32 %r_tmp2, 64, %r_iw;
    setp.lt.u32 %p3, %r_iw, 64;
    selp.b32 %r_tmp2, %r_tmp2, 0, %p3;
    min.u32 %r_tmp2, %r_tmp2, 4;
    shl.b32 %r_tmp2, %r_tmp2, 2;
    and.pred %p1, %p1, %p3;
    selp.b32 %r_tmp2, %r_tmp2, 0, %p1;
    mul.lo.u32 %r_tmp, %r_n, 3;
    add.u32 %r_tmp, %r_tmp, %r_stage_ic;
    mul.lo.u32 %r_tmp, %r_tmp, 64;
    add.u32 %r_tmp, %r_tmp, %r_id;
    mul.lo.u32 %r_tmp, %r_tmp, 64;
    add.u32 %r_tmp, %r_tmp, %r_ih;
    mul.lo.u32 %r_tmp, %r_tmp, 64;
    add.u32 %r_tmp, %r_tmp, %r_iw;
    cvt.u64.u32 %rd_off, %r_tmp;
    mul.lo.u64 %rd_off, %rd_off, 4;
    add.u64 %rd_addr, %rd_in, %rd_off;
    selp.b64 %rd_addr, %rd_addr, %rd_in, %p1;
    shl.b32 %r_tmp, %r_i, 4;
    add.u32 %r_tmp, %r_tmp, %r_stage_buf;
    add.u32 %r_soff, %r_sbase, %r_tmp;
    cp.async.ca.shared.global [%r_soff], [%rd_addr], 16, %r_tmp2;
    add.u32 %r_i, %r_i, 128;
    bra $Lstage0;
$Lstage0_done:
    cp.async.commit_group;
    // ---- per-thread output coordinates (2 along H x 4 adjacent along W) ----
    shr.u32 %r_kdl, %r_tid, 4;
    shr.u32 %r_tmp, %r_tid, 2;
    and.b32 %r_khl, %r_tmp, 3;
    and.b32 %r_kwl, %r_tid, 3;
    add.u32 %r_od, %r_id0, %r_kdl;
    shl.b32 %r_tmp, %r_khl, 1;
    add.u32 %r_oh, %r_ih0, %r_tmp;
    shl.b32 %r_tmp, %r_kwl, 2;
    add.u32 %r_ow, %r_iw0, %r_tmp;
    setp.lt.u32 %p1, %r_od, 62;
    setp.lt.u32 %p2, %r_oh, 61;
    and.pred %p_store, %p1, %p2;
    // thread-local input offset before selecting the channel buffer
    mul.lo.u32 %r_tmp, %r_kdl, 10;
    shl.b32 %r_tmp2, %r_khl, 1;
    add.u32 %r_tmp, %r_tmp, %r_tmp2;
    mul.lo.u32 %r_tmp, %r_tmp, 20;
    shl.b32 %r_tmp2, %r_kwl, 2;
    add.u32 %r_tmp, %r_tmp, %r_tmp2;
    shl.b32 %r_tmp, %r_tmp, 2;
    add.u32 %r_threadA, %r_sbase, %r_tmp;
    mov.f32 %f_acc0, 0f00000000;
    mov.f32 %f_acc1, 0f00000000;
    mov.f32 %f_acc2, 0f00000000;
    mov.f32 %f_acc3, 0f00000000;
    mov.f32 %f_acc4, 0f00000000;
    mov.f32 %f_acc5, 0f00000000;
    mov.f32 %f_acc6, 0f00000000;
    mov.f32 %f_acc7, 0f00000000;
    mov.u32 %r_ic, 0;
$Lcompute_channel:
    // Single-buffered input channel: wait for the staged channel, then use buffer 0.
    cp.async.wait_group 0;
    bar.sync 0;
    mov.u32 %r_inA, %r_threadA;
    mul.lo.u32 %r_tmp, %r_ic, 108;
    add.u32 %r_wA, %r_sbase, 8000;
    add.u32 %r_wA, %r_wA, %r_tmp;
    @!%p_store bra $Lfma_done;
    // kd=0: four H rows feed two output rows
    ld.shared.v4.f32 {%f_x0, %f_x1, %f_x2, %f_x3}, [%r_inA+0];
    ld.shared.v2.f32 {%f_x4, %f_x5}, [%r_inA+16];
    ld.shared.f32 %f_b0, [%r_wA+0];
    ld.shared.f32 %f_b1, [%r_wA+4];
    ld.shared.f32 %f_b2, [%r_wA+8];
    fma.rn.f32 %f_acc0, %f_x0, %f_b0, %f_acc0;
    fma.rn.f32 %f_acc0, %f_x1, %f_b1, %f_acc0;
    fma.rn.f32 %f_acc0, %f_x2, %f_b2, %f_acc0;
    fma.rn.f32 %f_acc1, %f_x1, %f_b0, %f_acc1;
    fma.rn.f32 %f_acc1, %f_x2, %f_b1, %f_acc1;
    fma.rn.f32 %f_acc1, %f_x3, %f_b2, %f_acc1;
    fma.rn.f32 %f_acc2, %f_x2, %f_b0, %f_acc2;
    fma.rn.f32 %f_acc2, %f_x3, %f_b1, %f_acc2;
    fma.rn.f32 %f_acc2, %f_x4, %f_b2, %f_acc2;
    fma.rn.f32 %f_acc3, %f_x3, %f_b0, %f_acc3;
    fma.rn.f32 %f_acc3, %f_x4, %f_b1, %f_acc3;
    fma.rn.f32 %f_acc3, %f_x5, %f_b2, %f_acc3;
    ld.shared.v4.f32 {%f_x0, %f_x1, %f_x2, %f_x3}, [%r_inA+80];
    ld.shared.v2.f32 {%f_x4, %f_x5}, [%r_inA+96];
    ld.shared.f32 %f_b3, [%r_wA+12];
    ld.shared.f32 %f_b4, [%r_wA+16];
    ld.shared.f32 %f_b5, [%r_wA+20];
    fma.rn.f32 %f_acc0, %f_x0, %f_b3, %f_acc0;
    fma.rn.f32 %f_acc0, %f_x1, %f_b4, %f_acc0;
    fma.rn.f32 %f_acc0, %f_x2, %f_b5, %f_acc0;
    fma.rn.f32 %f_acc1, %f_x1, %f_b3, %f_acc1;
    fma.rn.f32 %f_acc1, %f_x2, %f_b4, %f_acc1;
    fma.rn.f32 %f_acc1, %f_x3, %f_b5, %f_acc1;
    fma.rn.f32 %f_acc2, %f_x2, %f_b3, %f_acc2;
    fma.rn.f32 %f_acc2, %f_x3, %f_b4, %f_acc2;
    fma.rn.f32 %f_acc2, %f_x4, %f_b5, %f_acc2;
    fma.rn.f32 %f_acc3, %f_x3, %f_b3, %f_acc3;
    fma.rn.f32 %f_acc3, %f_x4, %f_b4, %f_acc3;
    fma.rn.f32 %f_acc3, %f_x5, %f_b5, %f_acc3;
    fma.rn.f32 %f_acc4, %f_x0, %f_b0, %f_acc4;
    fma.rn.f32 %f_acc4, %f_x1, %f_b1, %f_acc4;
    fma.rn.f32 %f_acc4, %f_x2, %f_b2, %f_acc4;
    fma.rn.f32 %f_acc5, %f_x1, %f_b0, %f_acc5;
    fma.rn.f32 %f_acc5, %f_x2, %f_b1, %f_acc5;
    fma.rn.f32 %f_acc5, %f_x3, %f_b2, %f_acc5;
    fma.rn.f32 %f_acc6, %f_x2, %f_b0, %f_acc6;
    fma.rn.f32 %f_acc6, %f_x3, %f_b1, %f_acc6;
    fma.rn.f32 %f_acc6, %f_x4, %f_b2, %f_acc6;
    fma.rn.f32 %f_acc7, %f_x3, %f_b0, %f_acc7;
    fma.rn.f32 %f_acc7, %f_x4, %f_b1, %f_acc7;
    fma.rn.f32 %f_acc7, %f_x5, %f_b2, %f_acc7;
    ld.shared.v4.f32 {%f_x0, %f_x1, %f_x2, %f_x3}, [%r_inA+160];
    ld.shared.v2.f32 {%f_x4, %f_x5}, [%r_inA+176];
    ld.shared.f32 %f_b0, [%r_wA+24];
    ld.shared.f32 %f_b1, [%r_wA+28];
    ld.shared.f32 %f_b2, [%r_wA+32];
    fma.rn.f32 %f_acc0, %f_x0, %f_b0, %f_acc0;
    fma.rn.f32 %f_acc0, %f_x1, %f_b1, %f_acc0;
    fma.rn.f32 %f_acc0, %f_x2, %f_b2, %f_acc0;
    fma.rn.f32 %f_acc1, %f_x1, %f_b0, %f_acc1;
    fma.rn.f32 %f_acc1, %f_x2, %f_b1, %f_acc1;
    fma.rn.f32 %f_acc1, %f_x3, %f_b2, %f_acc1;
    fma.rn.f32 %f_acc2, %f_x2, %f_b0, %f_acc2;
    fma.rn.f32 %f_acc2, %f_x3, %f_b1, %f_acc2;
    fma.rn.f32 %f_acc2, %f_x4, %f_b2, %f_acc2;
    fma.rn.f32 %f_acc3, %f_x3, %f_b0, %f_acc3;
    fma.rn.f32 %f_acc3, %f_x4, %f_b1, %f_acc3;
    fma.rn.f32 %f_acc3, %f_x5, %f_b2, %f_acc3;
    fma.rn.f32 %f_acc4, %f_x0, %f_b3, %f_acc4;
    fma.rn.f32 %f_acc4, %f_x1, %f_b4, %f_acc4;
    fma.rn.f32 %f_acc4, %f_x2, %f_b5, %f_acc4;
    fma.rn.f32 %f_acc5, %f_x1, %f_b3, %f_acc5;
    fma.rn.f32 %f_acc5, %f_x2, %f_b4, %f_acc5;
    fma.rn.f32 %f_acc5, %f_x3, %f_b5, %f_acc5;
    fma.rn.f32 %f_acc6, %f_x2, %f_b3, %f_acc6;
    fma.rn.f32 %f_acc6, %f_x3, %f_b4, %f_acc6;
    fma.rn.f32 %f_acc6, %f_x4, %f_b5, %f_acc6;
    fma.rn.f32 %f_acc7, %f_x3, %f_b3, %f_acc7;
    fma.rn.f32 %f_acc7, %f_x4, %f_b4, %f_acc7;
    fma.rn.f32 %f_acc7, %f_x5, %f_b5, %f_acc7;
    ld.shared.v4.f32 {%f_x0, %f_x1, %f_x2, %f_x3}, [%r_inA+240];
    ld.shared.v2.f32 {%f_x4, %f_x5}, [%r_inA+256];
    fma.rn.f32 %f_acc4, %f_x0, %f_b0, %f_acc4;
    fma.rn.f32 %f_acc4, %f_x1, %f_b1, %f_acc4;
    fma.rn.f32 %f_acc4, %f_x2, %f_b2, %f_acc4;
    fma.rn.f32 %f_acc5, %f_x1, %f_b0, %f_acc5;
    fma.rn.f32 %f_acc5, %f_x2, %f_b1, %f_acc5;
    fma.rn.f32 %f_acc5, %f_x3, %f_b2, %f_acc5;
    fma.rn.f32 %f_acc6, %f_x2, %f_b0, %f_acc6;
    fma.rn.f32 %f_acc6, %f_x3, %f_b1, %f_acc6;
    fma.rn.f32 %f_acc6, %f_x4, %f_b2, %f_acc6;
    fma.rn.f32 %f_acc7, %f_x3, %f_b0, %f_acc7;
    fma.rn.f32 %f_acc7, %f_x4, %f_b1, %f_acc7;
    fma.rn.f32 %f_acc7, %f_x5, %f_b2, %f_acc7;
    // kd=1
    ld.shared.v4.f32 {%f_x0, %f_x1, %f_x2, %f_x3}, [%r_inA+800];
    ld.shared.v2.f32 {%f_x4, %f_x5}, [%r_inA+816];
    ld.shared.f32 %f_b0, [%r_wA+36];
    ld.shared.f32 %f_b1, [%r_wA+40];
    ld.shared.f32 %f_b2, [%r_wA+44];
    fma.rn.f32 %f_acc0, %f_x0, %f_b0, %f_acc0;
    fma.rn.f32 %f_acc0, %f_x1, %f_b1, %f_acc0;
    fma.rn.f32 %f_acc0, %f_x2, %f_b2, %f_acc0;
    fma.rn.f32 %f_acc1, %f_x1, %f_b0, %f_acc1;
    fma.rn.f32 %f_acc1, %f_x2, %f_b1, %f_acc1;
    fma.rn.f32 %f_acc1, %f_x3, %f_b2, %f_acc1;
    fma.rn.f32 %f_acc2, %f_x2, %f_b0, %f_acc2;
    fma.rn.f32 %f_acc2, %f_x3, %f_b1, %f_acc2;
    fma.rn.f32 %f_acc2, %f_x4, %f_b2, %f_acc2;
    fma.rn.f32 %f_acc3, %f_x3, %f_b0, %f_acc3;
    fma.rn.f32 %f_acc3, %f_x4, %f_b1, %f_acc3;
    fma.rn.f32 %f_acc3, %f_x5, %f_b2, %f_acc3;
    ld.shared.v4.f32 {%f_x0, %f_x1, %f_x2, %f_x3}, [%r_inA+880];
    ld.shared.v2.f32 {%f_x4, %f_x5}, [%r_inA+896];
    ld.shared.f32 %f_b3, [%r_wA+48];
    ld.shared.f32 %f_b4, [%r_wA+52];
    ld.shared.f32 %f_b5, [%r_wA+56];
    fma.rn.f32 %f_acc0, %f_x0, %f_b3, %f_acc0;
    fma.rn.f32 %f_acc0, %f_x1, %f_b4, %f_acc0;
    fma.rn.f32 %f_acc0, %f_x2, %f_b5, %f_acc0;
    fma.rn.f32 %f_acc1, %f_x1, %f_b3, %f_acc1;
    fma.rn.f32 %f_acc1, %f_x2, %f_b4, %f_acc1;
    fma.rn.f32 %f_acc1, %f_x3, %f_b5, %f_acc1;
    fma.rn.f32 %f_acc2, %f_x2, %f_b3, %f_acc2;
    fma.rn.f32 %f_acc2, %f_x3, %f_b4, %f_acc2;
    fma.rn.f32 %f_acc2, %f_x4, %f_b5, %f_acc2;
    fma.rn.f32 %f_acc3, %f_x3, %f_b3, %f_acc3;
    fma.rn.f32 %f_acc3, %f_x4, %f_b4, %f_acc3;
    fma.rn.f32 %f_acc3, %f_x5, %f_b5, %f_acc3;
    fma.rn.f32 %f_acc4, %f_x0, %f_b0, %f_acc4;
    fma.rn.f32 %f_acc4, %f_x1, %f_b1, %f_acc4;
    fma.rn.f32 %f_acc4, %f_x2, %f_b2, %f_acc4;
    fma.rn.f32 %f_acc5, %f_x1, %f_b0, %f_acc5;
    fma.rn.f32 %f_acc5, %f_x2, %f_b1, %f_acc5;
    fma.rn.f32 %f_acc5, %f_x3, %f_b2, %f_acc5;
    fma.rn.f32 %f_acc6, %f_x2, %f_b0, %f_acc6;
    fma.rn.f32 %f_acc6, %f_x3, %f_b1, %f_acc6;
    fma.rn.f32 %f_acc6, %f_x4, %f_b2, %f_acc6;
    fma.rn.f32 %f_acc7, %f_x3, %f_b0, %f_acc7;
    fma.rn.f32 %f_acc7, %f_x4, %f_b1, %f_acc7;
    fma.rn.f32 %f_acc7, %f_x5, %f_b2, %f_acc7;
    ld.shared.v4.f32 {%f_x0, %f_x1, %f_x2, %f_x3}, [%r_inA+960];
    ld.shared.v2.f32 {%f_x4, %f_x5}, [%r_inA+976];
    ld.shared.f32 %f_b0, [%r_wA+60];
    ld.shared.f32 %f_b1, [%r_wA+64];
    ld.shared.f32 %f_b2, [%r_wA+68];
    fma.rn.f32 %f_acc0, %f_x0, %f_b0, %f_acc0;
    fma.rn.f32 %f_acc0, %f_x1, %f_b1, %f_acc0;
    fma.rn.f32 %f_acc0, %f_x2, %f_b2, %f_acc0;
    fma.rn.f32 %f_acc1, %f_x1, %f_b0, %f_acc1;
    fma.rn.f32 %f_acc1, %f_x2, %f_b1, %f_acc1;
    fma.rn.f32 %f_acc1, %f_x3, %f_b2, %f_acc1;
    fma.rn.f32 %f_acc2, %f_x2, %f_b0, %f_acc2;
